function ReasoningPart({
  text,
  status,
}: {
  text: string;
  status?: { type: string };
}) {
  const [open, setOpen] = useState(() => status?.type === "running");
  const userToggledRef = useRef(false);

  useEffect(() => {
    if (status?.type === "running") {
      userToggledRef.current = false;
      setOpen(true);
      return;
    }
    if (!userToggledRef.current) setOpen(false);
  }, [status?.type]);

  if (!text.trim()) return null;
  return (
    <details
      open={open}
      onToggle={(event) => {
        userToggledRef.current = true;
        setOpen(event.currentTarget.open);
      }}
      className={css({
        marginBottom: "0.75rem",
        borderRadius: "0.375rem",
        border: "1px solid var(--border)",
        backgroundColor: "color-mix(in srgb, var(--muted) 40%, transparent)",
        paddingInline: "0.75rem",
        paddingBlock: "0.5rem",
        fontSize: "0.75rem",
        color: "var(--muted-foreground)",
      })}
    >
      <summary
        className={css({
          display: "flex",
          cursor: "pointer",
          listStyle: "none",
          alignItems: "center",
          justifyContent: "space-between",
          gap: "0.5rem",
          fontWeight: 500,
        })}
      >
        <span>Reasoning</span>
        <CopyButton text={text} label="Copy" />
      </summary>
      <div className={css({ marginTop: "0.5rem", whiteSpace: "pre-wrap" })}>{text}</div>
    </details>
  );
}

function formatToolResult(result: unknown) {
  if (result === undefined) return "";
  if (typeof result === "string") return result;
  if (Array.isArray(result)) {
    const text = result
      .map((part) => {
        if (part?.type === "text" && typeof part.text === "string")
          return part.text;
        return "";
      })
      .filter(Boolean)
      .join("\n");
    if (text) return text;
  }
  return JSON.stringify(result, null, 2);
}

function ToolPart({
  toolName,
  args,
  result,
  isError,
  status,
  showDetails,
  showRawErrors,
}: {
  toolName: string;
