export const SHARE_LINK_MODE_OPTIONS: Array<{
	value: ShareLinkMode;
	label: string;
	description: string;
	public: boolean;
}> = [
	{
		value: "portable-short",
		label: "Portable short",
		description: "Short links that work across browsers when share storage is available.",
